void dostep(CubControl_FixedWingOuterLoop_t *m, real_t dt) {
    if (!m) {
        return;
    }
    real_t previous_time = m->time;
    real_t dx[1] = {0};
    derivative_rhs(m, dx);
    m->time += dt;
    process_periodic_events(m, previous_time);
    recalibrate(m);
}